library(tidyverse)
library(ggplot2)
library(maps)
library(leaflet)
library(sf)
library(tidycensus)

# Mayo Clinic campus data
mayo_data &lt;- tibble(
  state_name = c("arizona", "florida", "minnesota"),
  mayo_campus = c(1, 1, 1)
)

# Approximate locations of the three major Mayo Clinic campuses
mayo_locations &lt;- tibble(
  location = c(
    "Mayo Clinic Arizona",
    "Mayo Clinic Florida",
    "Mayo Clinic Rochester"
  ),
  state = c("Arizona", "Florida", "Minnesota"),
  longitude = c(-112.0740, -81.6557, -92.4630),
  latitude = c(33.4484, 30.3322, 44.0121)
)

# Static map data for Mayo Clinic
us_states &lt;- map_data("state")

mayo_states &lt;- us_states |&gt;
  left_join(mayo_data, by = c("region" = "state_name")) |&gt;
  mutate(mayo_campus = replace_na(mayo_campus, 0))

# Interactive map data for Mayo Clinic
states &lt;- read_sf(
  "https://rstudio.github.io/leaflet/json/us-states.geojson"
) |&gt;
  filter(!name %in% c("Alaska", "Hawaii", "District of Columbia"))

states_mayo &lt;- states |&gt;
  mutate(state_name = str_to_lower(name)) |&gt;
  left_join(mayo_data, by = "state_name") |&gt;
  mutate(mayo_campus = replace_na(mayo_campus, 0))

# Get 2024 uninsured rates from the American Community Survey
uninsured_data &lt;- get_acs(
  geography = "state",
  variables = c(uninsured_rate = "S2701_C05_001"),
  year = 2024,
  survey = "acs1"
) |&gt;
  select(NAME, estimate, moe) |&gt;
  rename(
    state_name = NAME,
    uninsured_rate = estimate,
    margin_of_error = moe
  ) |&gt;
  mutate(state_name = str_to_lower(state_name))

# Static map data for uninsured rates
uninsured_states &lt;- us_states |&gt;
  left_join(uninsured_data, by = c("region" = "state_name"))

# Interactive map data for uninsured rates
states_uninsured &lt;- states |&gt;
  mutate(state_name = str_to_lower(name)) |&gt;
  left_join(uninsured_data, by = "state_name")

3. Which words does Thor use most?
For my first text-analysis application, I counted words. I used unnest_tokens() from tidytext to separate lines into words, removed common words such as “the” and “and,” and counted what remained.


Show code
words &lt;- thor |&gt;
  select(section, clean_line) |&gt;
  unnest_tokens(word, clean_line) |&gt;
  anti_join(stop_words, by = "word")

common_words &lt;- words |&gt;
  count(word, sort = TRUE) |&gt;
  slice_head(n = 12)




Show code
common_words |&gt;
  ggplot(aes(x = n, y = reorder(word, n))) +
  geom_col(fill = "pink", color ="gray") +
  labs(title = "Thor's most common words", x = "Times used", y = "Word") +
  theme_minimal()








Figure 3: The 12 most frequent non-stop words in Thor’s dialogue.





The most common word after removing stop words is asgard, appearing 25 times. This chart shows which words Thor repeats most often after common stop words are removed. Frequent words can point toward important people or ideas, but a word count alone cannot tell us exactly what Thor means when he uses a word.
